from qiskit import QuantumCircuit

def build_oracle(qc: QuantumCircuit, problem_qubits: list[int], ancilla_qubits: list[int]) -> None:
    # Assign literal_ancillas, or_ancilla, and_ancilla
    literal_ancillas = ancilla_qubits[0:3]
    or_ancilla = ancilla_qubits[3]
    and_ancilla = ancilla_qubits[4]

    # Initialize and_ancilla to 1
    qc.x(and_ancilla)

    # List of clauses
    clauses = [
        [(1, True), (3, True), (6, False)],
        [(1, False), (6, False), (7, True)],
        [(2, True), (5, False), (6, True)],
        [(2, True), (3, True), (7, True)],
        [(0, False), (1, False), (6, True)],
        [(0, True), (1, False), (3, False)],
        [(2, False), (3, True), (6, True)],
        [(1, False), (4, True), (6, True)],
        [(2, True), (6, True), (7, False)]
    ]

    # Process each clause in compute phase
    for clause in clauses:
        used_literals = []
        for i, (var_idx, negated) in enumerate(clause):
            if negated:
                qc.x(literal_ancillas[i])
                qc.cx(problem_qubits[var_idx], literal_ancillas[i])
                used_literals.append( (literal_ancillas[i], var_idx) )
            else:
                used_literals.append( (problem_qubits[var_idx], None) )
        # Apply CNOTs to compute OR
        for literal in used_literals:
            if literal[1] is None:
                qc.cx(literal[0], or_ancilla)
            else:
                qc.cx(literal[0], or_ancilla)
        # Apply X/CNOT/X
        qc.x(or_ancilla)
        qc.cx(or_ancilla, and_ancilla)
        qc.x(or_ancilla)
        # Uncompute OR
        for literal in reversed(used_literals):
            if literal[1] is None:
                qc.cx(literal[0], or_ancilla)
            else:
                qc.cx(literal[0], or_ancilla)
        # Uncompute literals
        for i, (var_idx, negated) in enumerate(clause):
            if negated:
                qc.cx(problem_qubits[var_idx], literal_ancillas[i])
                qc.x(literal_ancillas[i])

    # Apply Z gate
    qc.z(and_ancilla)

    # Process each clause in reverse order for uncomputation
    for clause in reversed(clauses):
        used_literals = []
        for i, (var_idx, negated) in enumerate(clause):
            if negated:
                qc.x(literal_ancillas[i])
                qc.cx(problem_qubits[var_idx], literal_ancillas[i])
                used_literals.append( (literal_ancillas[i], var_idx) )
            else:
                used_literals.append( (problem_qubits[var_idx], None) )
        # Apply CNOTs to compute OR
        for literal in used_literals:
            if literal[1] is None:
                qc.cx(literal[0], or_ancilla)
            else:
                qc.cx(literal[0], or_ancilla)
        # Apply X/CNOT/X
        qc.x(or_ancilla)
        qc.cx(or_ancilla, and_ancilla)
        qc.x(or_ancilla)
        # Uncompute OR
        for literal in reversed(used_literals):
            if literal[1] is None:
                qc.cx(literal[0], or_ancilla)
            else:
                qc.cx(literal[0], or_ancilla)
        # Uncompute literals
        for i, (var_idx, negated) in enumerate(clause):
            if negated:
                qc.cx(problem_qubits[var_idx], literal_ancillas[i])
                qc.x(literal_ancillas[i])

    # Reset and_ancilla to 0
    qc.x(and_ancilla)
